To solve this problem, we need to transform an array into a "great" array using the minimum number of swap operations. A great array alternates between peaks and valleys either starting with a peak (pattern1) or a valley (pattern2). The allowed operation is to swap elements at positions i and N-i+1.

### Approach
1. **Pattern Analysis**: We need to check both possible patterns (starting with a peak or a valley) to determine the minimum number of swaps required.
2. **Pair Processing**: For each pair of elements (i, N-i+1), we check both possible configurations (swapped or not) to determine if they meet the required conditions for the current pattern.
3. **Local Validity Checks**: For each pair, we check if the elements satisfy the pattern conditions with their adjacent elements that have already been processed.
4. **Final Validation**: After processing all pairs, we perform a final check to ensure the entire array meets the pattern requirements.

### Solution Code
```python
import sys

def is_valid_pattern(arr, pattern):
    for i in range(len(arr)-1):
        if (i+1) % 2 == 1:  # 1-based is odd
            if pattern == 'pattern1':
                if not (arr[i] > arr[i+1]):
                    return False
            else:
                if not (arr[i] < arr[i+1]):
                    return False
        else:  # even
            if pattern == 'pattern1':
                if not (arr[i] < arr[i+1]):
                    return False
            else:
                if not (arr[i] > arr[i+1]):
                    return False
    return True

def compute_swaps(arr, pattern):
    n = len(arr)
    arr = arr.copy()
    swaps = 0
    for i in range(1, (n//2) +1):
        j = n - i +1
        current_i = arr[i-1]
        current_j = arr[j-1]
        option1_valid = True
        option2_valid = True

        # Check option1 (no swap)
        if i >1:
            prev = arr[i-2]
            if pattern == 'pattern1':
                if (i-1) %2 ==1:
                    if not (prev > current_i):
                        option1_valid = False
                else:
                    if not (prev < current_i):
                        option1_valid = False
            else:
                if (i-1) %2 ==1:
                    if not (prev < current_i):
                        option1_valid = False
                else:
                    if not (prev > current_i):
                        option1_valid = False
        if j <n:
            next_j = arr[j]
            if pattern == 'pattern1':
                if j%2 ==1:
                    if not (current_j > next_j):
                        option1_valid = False
                else:
                    if not (current_j < next_j):
                        option1_valid = False
            else:
                if j%2 ==1:
                    if not (current_j < next_j):
                        option1_valid = False
                else:
                    if not (current_j > next_j):
                        option1_valid = False

        # Check option2 (swap)
        new_i = current_j
        new_j = current_i
        if i >1:
            prev = arr[i-2]
            if pattern == 'pattern1':
                if (i-1) %2 ==1:
                    if not (prev > new_i):
                        option2_valid = False
                else:
                    if not (prev < new_i):
                        option2_valid = False
            else:
                if (i-1) %2 ==1:
                    if not (prev < new_i):
                        option2_valid = False
                else:
                    if not (prev > new_i):
                        option2_valid = False
        if j <n:
            next_j = arr[j]
            if pattern == 'pattern1':
                if j%2 ==1:
                    if not (new_j > next_j):
                        option2_valid = False
                else:
                    if not (new_j < next_j):
                        option2_valid = False
            else:
                if j%2 ==1:
                    if not (new_j < next_j):
                        option2_valid = False
                else:
                    if not (new_j > next_j):
                        option2_valid = False

        if not option1_valid and not option2_valid:
            return -1  # impossible

        if option1_valid and option2_valid:
            # Prefer to swap (option2) to potentially resolve future conditions
            arr[i-1] = new_i
            arr[j-1] = new_j
            swaps +=1
        elif option1_valid:
            arr[i-1] = current_i
            arr[j-1] = current_j
        else:
            arr[i-1] = new_i
            arr[j-1] = new_j
            swaps +=1

    if is_valid_pattern(arr, pattern):
        return swaps
    else:
        return -1

def solve():
    input = sys.stdin.read().split()
    ptr =0
    T = int(input[ptr])
    ptr +=1
    for _ in range(T):
        N = int(input[ptr])
        ptr +=1
        arr = list(map(int, input[ptr:ptr+N]))
        ptr +=N

        min_swaps = float('inf')
        res1 = compute_swaps(arr, 'pattern1')
        res2 = compute_swaps(arr, 'pattern2')
        possible = []
        if res1 != -1:
            possible.append(res1)
        if res2 != -1:
            possible.append(res2)
        if possible:
            print(min(possible))
        else:
            print(-1)

if __name__ == "__main__":
    solve()
```

### Explanation
1. **Pattern Check**: The `is_valid_pattern` function checks if the array meets the criteria for either pattern.
2. **Swap Computation**: The `compute_swaps` function processes each pair (i, N-i+1) and determines if swapping is necessary to meet the local conditions for the current pattern. It prefers swapping when both options are valid to resolve potential future conflicts.
3. **Final Check**: After processing all pairs, the solution validates the entire array to ensure it meets the pattern requirements.

This approach efficiently determines the minimum number of swaps needed by focusing on local validity checks and preferring swaps when both configurations are valid, ensuring a globally valid solution.

